import { createHash, randomUUID } from "node:crypto";
import { constants, lstatSync, realpathSync } from "node:fs";
import { link, open, unlink, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import type { PrivateVersionedStorage, StoredObject } from "./index.js";

const versionPattern = /^v2-fs-[a-f0-9]{64}$/u;
export const isV2FileVersion = (version: string) => versionPattern.test(version);

function hash(value: Uint8Array | string) {
  return createHash("sha256").update(value).digest("hex");
}

/** V2 proof commands supply generated bytes server-side after authorizing the job. */
export class V2FilesystemStorage implements PrivateVersionedStorage {
  static fromEnvironment() {
    const root = process.env.JOBGUARD_V2_STORAGE_DIR;
    if (process.env.JOBGUARD_LOCAL_V2 !== "1" || !root) return undefined;
    const workingDirectory = realpathSync(process.cwd());
    const checkout = workingDirectory.endsWith("/apps/web") ? dirname(dirname(workingDirectory)) : workingDirectory;
    if (root !== join(checkout, ".jobguard", "v2", "objects")) throw new Error("V2 storage target does not match");
    return new V2FilesystemStorage(root);
  }

  private readonly root: string;

  private constructor(root: string) {
    this.root = root;
    this.checkRoot();
  }

  private checkRoot() {
    for (const path of [dirname(dirname(this.root)), dirname(this.root), this.root]) {
      const info = lstatSync(path);
      if (!info.isDirectory() || realpathSync(path) !== path || info.uid !== process.getuid?.() || (info.mode & 0o077)) {
        throw new Error("V2 storage target is not a private directory");
      }
    }
  }

  private path(key: string, versionId: string) {
    this.checkRoot();
    if (!versionPattern.test(versionId) || !/^[a-z0-9-]+(?:\/[a-z0-9-]+)*$/iu.test(key)) {
      throw new Error("Invalid V2 storage object or version");
    }
    return join(this.root, `${hash(key)}-${versionId}`);
  }

  // Practice proof transfers are server-mediated. These references expose no object endpoint.
  async createUploadUrl({ key }: { key: string }) { return `urn:jobguard:v2:upload:${hash(key)}`; }
  async createDownloadUrl({ key, versionId }: { key: string; versionId: string }) {
    this.path(key, versionId);
    return `urn:jobguard:v2:object:${hash(key)}:${versionId}`;
  }

  async put(key: string, contentType: string, bytes: Uint8Array) {
    const body = Buffer.concat([Buffer.from(JSON.stringify(contentType) + "\n"), bytes]);
    const versionId = `v2-fs-${hash(body)}`;
    const destination = this.path(key, versionId);
    const temporary = join(this.root, `.upload-${randomUUID()}`);
    await writeFile(temporary, body, { flag: "wx", mode: 0o600 });
    try {
      await link(temporary, destination);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
      await this.readExactVersion(key, versionId);
    } finally {
      await unlink(temporary);
    }
    return versionId;
  }

  async readExactVersion(key: string, versionId: string): Promise<StoredObject> {
    await using file = await open(this.path(key, versionId), constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
    const info = await file.stat();
    if (!info.isFile() || info.uid !== process.getuid?.() || (info.mode & 0o077)) {
      throw new Error("Invalid V2 storage file");
    }
    const body = await file.readFile();
    if (`v2-fs-${hash(body)}` !== versionId) throw new Error("V2 storage version integrity check failed");
    const separator = body.indexOf(10);
    if (separator < 0) throw new Error("Invalid V2 storage metadata");
    const contentType: unknown = JSON.parse(body.subarray(0, separator).toString());
    if (typeof contentType !== "string") throw new Error("Invalid V2 storage metadata");
    const bytes = body.subarray(separator + 1);
    return { key, versionId, contentType, byteLength: bytes.length, bytes };
  }

  async deleteExactVersion(key: string, versionId: string) {
    await unlink(this.path(key, versionId));
  }
}
